create table if not exists public.website_publish_runs ( id uuid primary key default gen_random_uuid(), status text not null default 'running' check (status in ('running', 'finished', 'cancelled', 'failed')), total integer not null default 0, published integer not null default 0, skipped integer not null default 0, first_error text, skipped_ids uuid[] not null default '{}', ticks integer not null default 0, claimed_at timestamptz, started_by text not null, started_at timestamptz not null default timezone('utc', now()), finished_at timestamptz, status_reason text );
comment on table public.website_publish_runs is 'Background runs that publish ready draft listings. Internal only - no customer-facing policy exists, deliberately.';
alter table public.website_publish_runs enable row level security;
do $$ begin create policy "Admins manage website publish runs" on public.website_publish_runs for all using (public.is_admin()) with check (public.is_admin()); exception when duplicate_object then null; end; $$;
create or replace function public.website_publish_candidates( p_limit integer default 100, p_exclude uuid[] default '{}' ) returns table (id uuid) language sql stable security definer set search_path = public as $$ select w.id from public.websites w where w.status = 'draft' and not (w.id = any (p_exclude)) and exists ( select 1 from public.services s where s.website_id = w.id and s.available and s.price_minor > 0 ) order by w.id asc limit greatest(1, p_limit); $$;
create or replace function public.website_publish_eligible_count() returns integer language sql stable security definer set search_path = public as $$ select count(*)::integer from public.websites w where w.status = 'draft' and exists ( select 1 from public.services s where s.website_id = w.id and s.available and s.price_minor > 0 ); $$;
create or replace function public.claim_website_publish_run(p_stale_seconds integer default 600) returns uuid language plpgsql volatile security definer set search_path = public as $$ declare v_id uuid; begin update public.website_publish_runs r set claimed_at = timezone('utc', now()), ticks = r.ticks + 1 where r.id = ( select c.id from public.website_publish_runs c where c.status = 'running' and ( c.claimed_at is null or c.claimed_at < timezone('utc', now()) - make_interval(secs => greatest(60, p_stale_seconds)) ) order by c.started_at for update skip locked limit 1 ) returning r.id into v_id; return v_id; end; $$;
